"""The three committed example cases with their truth regenerated by the (deterministic) simulator."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

import pytest

from gst_recon.rewards import expand
from gst_recon.sim.world import generate_case

EXAMPLES = Path(__file__).resolve().parents[2] / "examples"
# case_id -> generate_case(seed, difficulty, index, split=...)
ARGS = {"easy-21-00001": (21, "easy", 1, "train"), "test_iid-hard-23-00001": (23, "hard", 1, "test_iid"),
        "test_ood-medium-22-00000": (22, "medium", 0, "test_ood")}


@lru_cache(maxsize=None)
def example(case_id: str):
    seed, diff, idx, split = ARGS[case_id]
    case = generate_case(seed, diff, idx, split=split)
    d = EXAMPLES / case_id
    target = json.loads((d / "target.json").read_text())
    assert case.expected.model_dump(mode="json") == expand(target), "simulator no longer reproduces the example"
    return (d / "prompt.txt").read_text(), target, case


@pytest.fixture(params=sorted(ARGS))
def ex(request):
    return example(request.param)
